INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72018, 'spa', 'Majestuoso y sublime', 'El genitivo femenino singular modifica a ''gloria,'' describiendo su cualidad sublime. Las traducciones interlingüísticas (español ''majestuosa,'' alemán ''majestätisch'') transmiten la magnificencia trascendente e imponente que Pedro presenció, una gloria tan abrumadora que validó todo lo que los apóstoles proclamaban acerca de la naturaleza y autoridad divina de Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72019, 'spa', 'Agrandar, ampliar', 'Hacer más grande, ampliar o aumentar en extensión física o figurada. En Mateo 23:5, Jesús critica a quienes ''agrandan'' sus filacterias — literalmente haciendo más anchas las cajitas de cuero como muestra de piedad. En 2 Corintios 10:15, Pablo expresa la esperanza de que, al crecer la fe de los corintios, su ámbito de ministerio sea ''engrandecido.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72020, 'spa', 'Magnificar, glorificar, exaltar', 'Magnificar, glorificar, alabar o exaltar — declarar la grandeza de Dios o tener a alguien en alto honor. Este es el sentido dominante en el NT (6 de 8 ocurrencias), anclado en el cántico de María en Lucas 1:46: ''Mi alma engrandece al Señor.'' En Hechos 10:46 la familia de Cornelio fue oída ''magnificando a Dios,'' y en Hechos 19:17 el nombre del Señor Jesús ''era magnificado.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72027, 'spa', 'Grandemente, en gran manera', 'La forma adverbial intensifica el verbo ''me regocijé'': ''me regocijé grandemente.'' La evidencia interlingüística (español ''grandemente,'' alemán ''sehr'') muestra que funciona como modificador de grado, enfatizando la magnitud de la respuesta emocional de Pablo ante el renovado interés de los filipenses, que reflejaba tanto su amor como su crecimiento espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72028, 'spa', 'Majestad divina', 'Majestad, específicamente la grandeza y soberanía divinas. Hebreos 1:3 y 8:1 emplean «la Majestad» como título de Dios: Cristo «se sentó a la diestra de la Majestad en las alturas» tras purificar los pecados (1:3) y está ahora «sentado a la diestra del trono de la Majestad en los cielos» (8:1). Judas 25 atribuye «gloria, majestad, dominio y autoridad» a Dios por medio de Jesucristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72029, 'spa', 'grande en tamaño o extensión', 'Grande en tamaño físico, extensión espacial o magnitud general, con 176 apariciones como sentido dominante. Abarca grandes ciudades (Ap 11:8), multitudes numerosas (Mt 14:14), grandes luces (Mt 4:16), voces fuertes (Ap 1:10), grandes tormentas (Mt 8:24) y gran gozo (Mt 2:10). Español gran/grande cubre este abanico con naturalidad. La amplitud de este grupo refleja el papel de μέγας como adjetivo de magnitud no marcado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72030, 'spa', 'mayor o el más grande', 'Formas comparativas y superlativas — 49 apariciones de μείζων (''mayor'') y μέγιστος (''el más grande''). Central en la enseñanza de Jesús sobre la inversión del reino: ''el mayor entre vosotros será vuestro servidor'' (Mt 23:11); ''entre los nacidos de mujer no se ha levantado otro mayor que Juan'' (Mt 11:11). El español emplea mayor tanto para el comparativo como para el superlativo, con gran carga teológica en estos pasajes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72032, 'spa', 'grande en importancia o rango', 'Grande en importancia, rango o estatus social — 10 apariciones donde μέγας se usa sustantiva o atributivamente para personas de alta posición. En Mt 20:25 ''los grandes'' ejercen autoridad; en Hch 26:22 Pablo testifica ante ''grandes y pequeños''. Se superpone con el sentido 2 pero se centra en la jerarquía social más que en la comparación de grado. Equivale a los notables o los poderosos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72033, 'spa', 'grandes cosas u obras', 'Grandes cosas u obras — 3 apariciones donde μέγας se sustantiva en neutro para significar ''grandes cosas'' u ''obras poderosas''. El Magnificat de María: ''grandes cosas ha hecho por mí el Poderoso'' (Lc 1:49); Santiago advierte que la lengua ''se jacta de grandes cosas'' (Stg 3:5); la bestia ''habla grandes cosas'' (Ap 13:5). Español grandes cosas nominaliza el adjetivo de forma natural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72035, 'spa', 'grande en intensidad', 'Grande en intensidad — 4 apariciones donde el énfasis recae en la severidad o el volumen más que en el tamaño físico. Una ''gran fiebre'' (Lc 4:38), Pablo que clama ''a gran voz'' (Hch 14:10; 16:28), y Festo declarando que las ''muchas letras'' de Pablo lo han enloquecido (Hch 26:24). La función intensificadora se distingue del tamaño: español emplea intenso o fuerte junto a grande.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72050, 'spa', 'grande en cantidad', 'Grande en cantidad — una sola aparición en Hch 26:29 donde Pablo desea ''en gran medida'' que todos los que le escuchan se hagan cristianos. Aquí μέγας significa ''mucho'' o ''en alto grado'' más que tamaño físico o estatus. Un sentido marginal pero real en el límite del campo semántico del adjetivo, donde español mucho desplaza a grande.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72051, 'spa', 'Grandeza, magnitud', 'El nominativo neutro singular funciona como sujeto: ''cuál es la supereminente grandeza.'' Las traducciones interlingüísticas (español ''grandeza,'' alemán ''Größe'') enfatizan el concepto de inmensidad o magnitud aplicado al poder de Dios, que Pablo presenta como incalculable pero cognoscible mediante la iluminación espiritual, accesible a través de la obra reveladora del Espíritu.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72052, 'spa', 'Magnates y poderosos', 'Grandes, nobles o magnates: personas poderosas, ricas e influyentes. Marcos 6:21 describe el banquete de Herodes para «sus nobles, comandantes militares y los principales de Galilea», la élite de su reino. Apocalipsis 6:15 enumera a quienes huyen de la ira de Dios: «reyes, grandes, generales, ricos y poderosos», mostrando que el estatus mundano no ofrece escape ante el juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72053, 'spa', 'Traducir, interpretar', 'Trasladar una expresión o un nombre de un idioma a otro, funcionando como marcador metalingüístico en el texto neotestamentario. Se usa casi exclusivamente en participio pasivo (μεθερμηνευόμενον, ''siendo traducido'') cuando los evangelistas explican términos semíticos a lectores griegos: ''Emmanuel... que traducido es, Dios con nosotros'' (Mateo 1:23), ''Talita cum... que traducido es, Niña, levántate'' (Marcos 5:41).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72055, 'spa', 'Embriaguez', 'Embriaguez, intoxicación o hábito de beber en exceso. Jesús advierte en Lucas 21:34 que no se carguen los corazones de «disipación y embriaguez», pues la embriaguez embota la vigilancia espiritual. Pablo la incluye entre los vicios: Romanos 13:13 contrasta la conducta recta con «orgías y borracheras», y Gálatas 5:21 la clasifica como obra de la carne con graves consecuencias eternas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72056, 'spa', 'Remover o trasladar', 'Remover, trasladar o desplazar a alguien de una posición, autoridad o estado a otro. Implica reubicación intencional y autoritativa. Dios ''removió'' a Saúl como rey (Hch 13:22); los creyentes son ''trasladados'' de las tinieblas al reino de Cristo (Col 1:13); la fe podría ''remover'' montañas (1 Co 13:2). En Lucas 16:4 el mayordomo teme ser ''removido'' de su cargo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72058, 'spa', 'Embriagar o embriagarse', 'Intoxicarse o causar intoxicación, usado tanto literalmente de la ebriedad por vino como metafóricamente del aturdimiento por influencias seductoras. Lucas 12:45 y 1 Tesalonicenses 5:7 lo emplean literalmente respecto al consumo de alcohol; Efesios 5:18 contrasta el vino con la plenitud del Espíritu; Apocalipsis 17:2 lo extiende a la embriaguez figurada con la inmoralidad de Babilonia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72060, 'spa', 'Estar ebrio, embriagarse', 'Hallarse en estado de embriaguez o intoxicación por vino o bebida fuerte. El sentido literal predomina: Mateo 24:49 describe a un siervo bebiendo con borrachos, 1 Tesalonicenses 5:7 señala que los que se embriagan lo hacen de noche, y 1 Corintios 11:21 reprende a quienes llegan ebrios a la cena comunitaria. Juan 2:10 emplea el término de manera socialmente descriptiva, sin carga moral, al señalar que los invitados ya habían bebido abundantemente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72066, 'spa', 'Tinta para escribir', 'El líquido de escritura empleado con pluma sobre pergamino o papiro. Las tres apariciones en el NT contrastan la tinta con la relación viva: la metáfora paulina del Espíritu frente a la tinta (2 Co 3:3) y la preferencia de Juan por la presencia personal sobre la correspondencia escrita (2 Jn 12; 3 Jn 13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72067, 'spa', 'Color negro', 'El color negro, usado tanto en sentido literal (del cabello en Mt 5:36) como simbólico (de juicio y hambruna en las visiones apocalípticas). El griego μέλας cubre el rango semántico desde la oscuridad concreta hasta la penumbra figurada, manteniéndose como término cromático básico en los tres pasajes neotestamentarios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72068, 'spa', 'Antepasado genealógico', 'La forma genitiva sitúa a este antepasado dentro de la cadena de descendencia. La preservación interlingüística de la transliteración griega mantiene la integridad genealógica del registro de Lucas; cada nombre, aunque oscuro, contribuye al argumento acumulativo de la legítima pretensión de Jesús al trono de David mediante ascendencia biológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72070, 'spa', 'Miel', 'Miel, la sustancia naturalmente dulce producida por las abejas, a veces especificada como miel silvestre. En Mateo 3:4 y Marcos 1:6 describe la miel silvestre consumida por Juan el Bautista en el desierto de Judea. En Apocalipsis 10:9-10 sirve como símil de la dulzura inicial de la palabra profética de Dios, que luego se torna amarga al asimilar su mensaje de juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72071, 'spa', 'Isla de Malta', 'La forma nominativa identifica la isla por su nombre. La evidencia multilingüe (francés ''Malte'') confirma la identificación posterior con la Malta moderna, aunque existió debate antiguo sobre la ubicación precisa. El relato de Lucas subraya la providencia divina: incluso el naufragio se convierte en oportunidad para el avance del evangelio y la demostración milagrosa del poder de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72072, 'spa', 'estar a punto de', 'El sentido perifrástico central: estar a punto de, ir a hacer algo. Este uso abrumadoramente dominante crea una construcción de futuro próximo que señala inminencia. Aparece en todos los tiempos, personas y modos, desde la narración (Mt 2:13; Mt 17:22) hasta la revelación apocalíptica (las cosas que están a punto de suceder). Español a punto de e ir a captan el umbral entre la intención y la acción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72079, 'spa', 'venidero, futuro', 'El participio adjetival o sustantivado: venidero, futuro, por venir. Aquí el participio modifica un sustantivo (''la ira venidera'', Mt 3:7; ''el siglo venidero'', Mt 12:32) o aparece solo (''las cosas venideras'', Hch 24:25). Este sentido está estrechamente vinculado al sentido 1 pero ha pasado de auxiliar verbal a modificador. Lucas lo emplea con frecuencia para caracterizar realidades escatológicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72093, 'spa', 'estar dispuesto', 'Un sentido de disposición, voluntad o preparación intencional. En 2 Pe 1:12 el autor dice ''estaré siempre dispuesto a recordaros estas cosas'' — aquí el verbo no transmite inminencia sino prontitud deliberada. Español estaré dispuesto apunta hacia la preparación volitiva más que hacia la cercanía temporal. Este uso conecta con el sentido del griego clásico de proponerse o tener la intención.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72097, 'spa', 'demorar, vacilar', 'Un sentido de demora o vacilación, atestiguado en Hch 22:16 donde Ananías interpela a Saulo: ''¿por qué te demoras?'' (τί μέλλεις). Español ¿qué esperas? capta bien el matiz. Esta inversión — de ''estar a punto de actuar'' a ''no llegar a actuar'' — explota la implicación de que quien está al borde de algo aún no lo ha hecho. El uso clásico de μέλλω para la vacilación subyace aquí.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72120, 'spa', 'Extremidad u organo del cuerpo fisico, extendido metaforicamente a la comunidad ', 'Extremidad u organo del cuerpo fisico, extendido metaforicamente a la comunidad de creyentes. Jesus lo emplea para el ojo y la mano en sus dichos de discipulado radical (Mt 5:29-30). Pablo desarrolla una doble aplicacion: etica, como partes del cuerpo ofrecidas al pecado o a la justicia (Ro 6:13; 7:23), y eclesiologica, como partes interdependientes del cuerpo de Cristo (1 Co 12:12-27). Santiago advierte que la lengua, aunque miembro pequeno, incendia todo el cuerpo (Stg 3:5-6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72124, 'spa', 'Melquisedec', 'El nombre propio Melquisedec (hebreo ''mi rey es justicia''), el rey-sacerdote de Salem que bendijo a Abraham (Génesis 14:18-20). Las ocho ocurrencias en el NT se encuentran en Hebreos, donde el autor desarrolla un extenso argumento tipológico: Cristo posee un sacerdocio ''según el orden de Melquisedec'' (Hebreos 5:6; 6:20; 7:1, 11, 15, 17), superior al orden levítico por ser sin principio ni fin.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72125, 'spa', 'Verbo impersonal que significa ''importar, preocupar, ser motivo de interés'' para', 'Verbo impersonal que significa ''importar, preocupar, ser motivo de interés'' para alguien, generalmente con μέλει + dativo de persona. Usado negativamente para expresar indiferencia: los discípulos reprochan a Jesús en la tempestad (Mr 4:38), al asalariado no le importan las ovejas (Jn 10:13), a Judas no le importaban los pobres (Jn 12:6), a Galión no le importaban las disputas judías (Hch 18:17). Usado positivamente del cuidado de Dios por los creyentes (1 P 5:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72134, 'spa', 'Pergaminos para escritura', 'El acusativo femenino plural ''los pergaminos'' identifica documentos específicos que Pablo quería recuperar. La evidencia interlingüística (español ''pergaminos'', alemán ''Pergament'') confirma que se trata de pieles animales tratadas para la escritura, distinguiéndolas de los ''libros'' (probablemente rollos de papiro) mencionados junto a ellos, enfatizando la preocupación de Pablo por los materiales escritos aun en su encarcelamiento final.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72136, 'spa', 'Quejumbroso descontento', 'El nominativo masculino plural ''quejosos'' caracteriza a estos falsos maestros. La evidencia interlingüística (español ''quejosos'', alemán ''Unzufriedene'') transmite la actitud habitual de hallar faltas y el descontento que marca a quienes rechazan la autoridad de Dios, crónicamente insatisfechos porque resisten la fuente misma de satisfacción: la sumisión a los buenos propósitos del Creador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72137, 'spa', 'ciertamente, por una parte', 'Partícula discursiva con doble función: (a) énfasis afirmativo (''ciertamente, en verdad'') cuando aparece sola, y (b) marcador correlativo que introduce el primer miembro de un contraste μέν...δέ (''por una parte...por otra''). El francés d''une part y el alemán zwar revelan la estructura contrastiva con más transparencia que el español, donde la partícula frecuentemente se absorbe en el orden de palabras. Omnipresente en Hechos y las epístolas paulinas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72146, 'spa', 'Corrección enfática', 'Partícula enfática que introduce una contraafirmación o afirmación rotunda, traducible como ''más bien'', ''por el contrario'' o ''ciertamente''. Corrige o intensifica lo dicho previamente. Su doble función —adversativa y afirmativa— se refleja en los contextos del NT: reprensión (Ro 9:20), confirmación retórica (Ro 10:18) y redefinición de la bienaventuranza (Lc 11:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72147, 'spa', 'Sin embargo', 'Conjunción concesiva que significa ''sin embargo'' o ''no obstante,'' reconociendo un pensamiento previo mientras introduce una declaración contrastante o matizadora. Aparece en Juan 4:27 (querían preguntar, pero nadie habló), Juan 7:13 (nadie hablaba abiertamente, sin embargo, por miedo) y Juan 20:5. El español ''sin embargo'' capta bien este matiz adversativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72148, 'spa', 'Ciertamente', 'Partícula afirmativa enfática que significa ''ciertamente'' o ''en verdad,'' otorgando peso y certeza a la afirmación que sigue. En Juan 12:42, muchos de los gobernantes ciertamente creyeron pero temían a los fariseos; en Santiago 2:8, cumplir la ley real es ciertamente hacer bien. El español ''ciertamente'' resalta la fuerza afirmativa más que la contrastiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72149, 'spa', 'No obstante', 'Conjunción adversativa fuerte que significa ''no obstante,'' marcando un giro decisivo desde una situación inquietante hacia una verdad reconfortante. En 2 Timoteo 2:19, a pesar de quienes se han desviado de la verdad, ''no obstante, el fundamento firme de Dios permanece.'' El español ''no obstante'' confirma el peso concesivo-adversativo de esta partícula.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72151, 'spa', 'permanecer, persistir', 'Permanecer, continuar o persistir en un estado, relación o condición — el sentido más frecuente con 79 apariciones, teológicamente dominante en la literatura joánica. En Jn 15:4-10 Jesús ordena repetidamente ''permaneced en mí'', haciendo de μένω el verbo emblemático de la inhabitación espiritual y la unión de pacto. En 1 Jn 2:6 quien dice que ''permanece en él'' debe andar como Cristo anduvo. Español permanecer capta esta dimensión relacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72153, 'spa', 'quedarse, alojarse', 'Quedarse o alojarse en un lugar físico durante un período de tiempo — 27 apariciones de permanencia concreta y espacial. En Lc 1:56 María ''se quedó con'' Elisabet unos tres meses; en Lc 19:5 Jesús dice a Zaqueo ''hoy debo quedarme en tu casa''; en Lc 24:29 los discípulos de Emaús ruegan al Cristo resucitado que ''se quede con ellos''. En Jn 1:39 Jesús invita a los primeros discípulos a ''venir y ver'', y ''se quedaron con él aquel día''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72165, 'spa', 'perdurar, durar', 'De cosas, verdades o estados que perduran, resisten o permanecen en el tiempo — 10 apariciones donde la permanencia importa más que la presencia. En 1 Co 13:13 ''permanecen la fe, la esperanza y el amor'' — la célebre tríada que sobrevive a todos los carismas. En Jn 6:27 Jesús contrasta el alimento perecedero con el que ''permanece'' para vida eterna. En 1 Pe 1:25 ''la palabra del Señor permanece para siempre''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72170, 'spa', 'esperar, aguardar', 'Esperar o aguardar a alguien — 2 apariciones en Hechos. En Hch 20:5 los compañeros de Pablo ''nos esperaban'' en Troas, y en Hch 20:23 Pablo dice que prisiones y tribulaciones ''me esperan'' en Jerusalén. Español me esperan emplea un verbo dedicado a la espera, distinto de permanecer, reflejando un desplazamiento léxico del sentido de ''quedarse'' al de ''aguardar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72195, 'spa', 'Dividir o estar dividido', 'Dividir o estar dividido: separar en partes opuestas o encontrarse en un estado de división interna, usado para reinos, hogares y lealtades desgarradas por el conflicto. La advertencia de Jesús en Mt 12:25-26 de que un reino dividido contra sí mismo será asolado constituye el uso paradigmático. Mc 3:24-26 repite el patrón: si Satanás está dividido contra sí mismo, no puede subsistir.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72196, 'spa', 'Repartir, distribuir', 'Repartir, distribuir: asignar, repartir o adjudicar porciones de algo, enfatizando el acto de distribuir recursos, dones o responsabilidades por parte de alguien con autoridad. En Mc 6:41 Jesús repartió los panes entre sus discípulos para distribución a la multitud. Pablo usa el sentido activo en Ro 12:3 y 1 Co 7:17 para referirse a Dios midiendo la fe y el llamado a cada persona.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72203, 'spa', 'Ansiedad, afán, preocupación', 'Inquietud ansiosa o preocupación absorbente por las circunstancias de la vida, especialmente asuntos mundanos que compiten con la atención espiritual. En la Parábola del Sembrador, μέριμνα representa los afanes y ansiedades que ahogan la semilla de la palabra de Dios (Mateo 13:22; Marcos 4:19; Lucas 8:14). Lucas 21:34 advierte contra corazones abrumados por las ansiedades de la vida. Pablo le da al término una coloración distinta en 2 Corintios 11:28, donde su ''preocupación por todas las iglesias'' refleja una solicitud legítima y piadosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72208, 'spa', 'Estar ansioso, preocuparse', 'Estar ansioso, preocuparse: Estar turbado por la ansiedad, preocuparse por las provisiones terrenales, la seguridad o el futuro — con una connotación claramente negativa de desconfianza. La prohibición reiterada de Jesús en Mateo 6:25-34 hace de este el paradigma neotestamentario de advertencia contra la ansiedad. El español «estéis ansiosos» y el alemán «sich sorgen» capturan la cualidad inquieta y consumidora. El paralelo en Lucas 12:22-26 y Filipenses 4:6 («por nada estéis afanosos») refuerza este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72209, 'spa', 'Interesarse por, preocuparse genuinamente', 'Interesarse por, preocuparse genuinamente: Tener interés genuino y positivo por el bienestar de alguien o por asuntos de importancia espiritual. Pablo lo emplea en 1 Corintios 7:32-34, donde la persona soltera «se preocupa por las cosas del Señor», y en 12:25, donde los miembros del cuerpo «se preocupan los unos por los otros». El español «se preocupa» cubre ambos sentidos, pero el contexto aquí desplaza la valencia de la preocupación ansiosa al cuidado genuino y abnegado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72217, 'spa', 'Porción o parte', 'Parte, porción o lote asignado, ya sea material, espiritual o relacional. Abarca la elección de María de la buena ''parte'' a los pies de Jesús (Lucas 10:42), la participación de los santos en la herencia de la luz (Colosenses 1:12), la pregunta retórica sobre qué ''parte'' tiene Cristo con Belial (2 Corintios 6:15), y se extiende también a un distrito geográfico (Hechos 16:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72219, 'spa', 'Repartidor de bienes', 'El acusativo masculino singular funciona como objeto: ''un repartidor sobre vosotros''. Los equivalentes interlingüísticos (español ''repartidor'', francés ''celui-qui-partage'') identifican a quien asigna porciones o herencias, una función jurídico-económica que Jesús rechaza explícitamente, redirigiendo la atención de la división material hacia prioridades espirituales que trascienden las preocupaciones patrimoniales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72220, 'spa', 'Parte, porcion o participacion de un todo', 'Parte, porcion o participacion de un todo. Abarca tanto divisiones concretas (el amo parte al siervo infiel, Mt 24:51; el prodigo pide su porcion de la herencia, Lc 15:12) como usos abstractos como ek merous (''en parte'', 1 Co 13:9-12). El apice teologico es Juan 13:8, donde ''tener parte'' conmigo connota participacion en el pacto y herencia espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72222, 'spa', 'Region, distrito o territorio geografico, con 7 apariciones concentradas en Mate', 'Region, distrito o territorio geografico, con 7 apariciones concentradas en Mateo y Hechos. El hijo de Herodes gobierna ''en la region de Galilea'' (Mt 2:22); Jesus se retira ''a las partes de Tiro y Sidon'' (Mt 15:21); Pablo recorre ''las regiones superiores'' de Asia Menor (Hch 19:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72223, 'spa', 'Seccion, division o lado de una estructura fisica o grupo', 'Seccion, division o lado de una estructura fisica o grupo. Los soldados dividen las vestiduras de Jesus ''en cuatro partes'' (Jn 19:23); los discipulos echan la red ''al lado derecho'' de la barca (Jn 21:6); Apocalipsis 16:19 parte a Babilonia ''en tres partes''. El enfasis recae en las divisiones constitutivas de una entidad mayor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72230, 'spa', 'Turno en una secuencia', 'Turno en una secuencia. Aparicion unica en 1 Corintios 14:27, donde Pablo instruye que los que hablan en lenguas deben hablar ''por turno'' (ana meros). Este uso idiomatico con la preposicion ana crea un significado rotativo-secuencial ya presente en el griego clasico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72231, 'spa', 'Trozo o fragmento fisico', 'Trozo o fragmento fisico. Aparicion unica en Lucas 24:42, donde al Jesus resucitado le ofrecen ''un pedazo de pescado asado''. Aqui meros es concreto y tangible: no la division de un todo abstracto, sino un fragmento material de alimento. El contexto de la comida postresurreccional da a este sentido humilde una resonancia teologica inesperada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72233, 'spa', 'Mediar como garante', 'El aoristo activo en tercera persona del singular, ''garantizó'', describe la acción confirmatoria de Dios. Las traducciones interlingüísticas (español ''medió'', alemán ''vermitteln'') transmiten la función mediadora; sin embargo, lo singular aquí es que Dios media su propia promesa, añadiendo un juramento para hacer el pacto absolutamente seguro, mostrando la condescendencia divina ante la necesidad humana de certeza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72234, 'spa', 'Mediador, intermediario', 'Aquel que se sitúa entre dos partes para lograr reconciliación, acuerdo o establecimiento de un pacto. Moisés es identificado como mediador del pacto sinaítico (Gálatas 3:19-20), donde Pablo razona que un mediador implica más de una parte, subrayando la naturaleza condicional de la Ley. La mediación de Cristo constituye el clímax teológico: él es el único mediador entre Dios y la humanidad (1 Timoteo 2:5) y el mediador de un pacto mejor (Hebreos 8:6; 9:15; 12:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72236, 'spa', 'Medianoche', 'Medianoche, el punto medio de la noche, empleado como marcador temporal para momentos narrativamente significativos. En Marcos 13:35 es una de las vigilias durante las cuales el señor puede regresar inesperadamente. Hechos 16:25 sitúa la adoración milagrosa de Pablo y Silas a esa hora. Lucas 11:5 presenta un visitante nocturno, y Hechos 20:7 describe la predicación prolongada de Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72238, 'spa', 'en medio, centro', 'El centro o interior de un espacio o reunión, usado sustantivadamente o como adjetivo locativo. Espacialmente: en medio de lobos (Mt 10:16), un niño en medio (Mt 18:2), en el Areópago (Hch 17:22). Temporalmente: medianoche (Hch 27:27), mediados de la fiesta (Jn 7:14). Socialmente: Cristo «en medio» de los suyos (Mt 18:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72247, 'spa', 'Pared divisoria', 'El acusativo neutro singular, ''la pared intermedia'', identifica lo que Cristo demolió. Las traducciones interlingüísticas (español ''pared-intermedia'', alemán ''Scheidewand'') enfatizan la función de barrera: una estructura diseñada para separar y excluir. La obra de Cristo elimina esta partición, creando unidad donde antes la división definía las relaciones, reconciliando a ambos grupos con Dios en un solo cuerpo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72248, 'spa', 'Cenit celeste', 'El cenit o punto meridiano del cielo, el arco más alto donde culminan los cuerpos celestes. En las visiones de Apocalipsis, es la posición desde la cual los ángeles hacen proclamaciones destinadas a alcanzar a todos los habitantes de la tierra. El griego μεσουράνημα es un término técnico que denota el punto culminante de la bóveda celeste.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72249, 'spa', 'Estar a la mitad', 'El participio presente en genitivo femenino, ''estando a la mitad'', describe el estado temporal de la fiesta. Las traducciones interlingüísticas (español ''mediada'', francés ''au-milieu'') indican que se ha alcanzado el punto medio, mostrando el momento deliberado de Jesús al revelarse públicamente, ni al inicio ni al final del festival, sino cuando la oportunidad de enseñanza era máxima.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72251, 'spa', 'Lleno, colmado', 'Completamente lleno, ya sea de contenido físico o de cualidades abstractas. El uso literal aparece en Juan 19:29 (un vaso lleno de vinagre) y Juan 21:11 (una red llena de peces), donde el énfasis recae en la capacidad alcanzada. La extensión figurada — ''llenos de hipocresía'' (Mateo 23:28), ''llenos de envidia y homicidio'' (Romanos 1:29), ''llenos de maldición y amargura'' (Romanos 3:14) — tiene mayor carga teológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72253, 'spa', 'Llenar por completo', 'El participio perfecto pasivo en nominativo masculino plural, ''habiendo sido llenados'', describe el supuesto estado de los discípulos. Las traducciones interlingüísticas (español ''llenos'', francés ''remplir'') enfatizan la saturación completa. La explicación de los burladores sustituye la embriaguez física por el llenado espiritual, sin comprender que se estaba manifestando un genuino empoderamiento divino en formas que les parecían irracionales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72254, 'spa', 'con', 'Compañía, asociación o participación, rigiendo el caso genitivo. Con 368 apariciones es el sentido primario: estar con alguien (Mt 2:3, Herodes ''con toda Jerusalén''), actuar juntos (Mt 5:41, ''camina con él dos millas'') o poseer una cualidad acompañante. La evidencia interlingüística es uniforme: español con, francés avec, alemán mit, todos marcadores dedicados de compañía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72255, 'spa', 'después de', 'Sucesión o secuencia temporal, rigiendo el caso acusativo, con el significado de ''después de''. Con 105 apariciones introduce expresiones temporales: ''después de seis días'' (Mt 17:1), ''después de dos días'' (Mt 26:2), ''después de la tribulación de aquellos días'' (Mt 24:29). El sentido temporal activa un vocabulario enteramente diferente en las lenguas receptoras: español después de, alemán nach, francés après.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72258, 'spa', 'Partir, irse físicamente', 'Partir, irse físicamente: movimiento de un lugar a otro, el uso más frecuente en el Nuevo Testamento. Jesús ''partió de allí'' (Mt 11:1; 12:9; 15:29) mientras avanzaba en su ministerio itinerante. El español alterna entre ''partió'' y ''pasó'', enfatizando siempre el dejar un lugar para ir a otro. Las ocho apariciones conforman la columna narrativa de los desplazamientos de Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72262, 'spa', 'Pasar, transitar espiritualmente', 'Pasar, transitar espiritualmente: pasar de un estado a otro, especialmente en el profundo sentido metafórico de cruzar de la muerte a la vida. Juan 5:24 declara que el creyente ''ha pasado de muerte a vida,'' y 1 Juan 3:14 hace eco: ''hemos pasado de muerte a vida.'' El español ''ha pasado'' sirve tanto para el sentido físico como espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72263, 'spa', 'Moverse, trasladarse', 'Moverse, trasladarse: cambiar de posición, con énfasis en el cambio de ubicación más que en la partida, ya sea de objetos o personas que se reubican. Jesús dice que la fe podría ordenar a un monte: ''Pásate de aquí allá, y se pasará'' (Mt 17:20), e instruye a los setenta y dos a permanecer en una casa sin mudarse de casa en casa (Lc 10:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72268, 'spa', 'Cambiar de opinión', 'El participio aoristo medio en nominativo masculino plural, ''habiendo cambiado de opinión'', describe la inversión de juicio de los nativos. Las traducciones interlingüísticas (español ''habiendo-cambiado-de-opinión'', francés ''changer'') transmiten el cambio radical de valoración: de suponer un castigo divino a atribuir naturaleza divina, ambas conclusiones incorrectas, pero que crearon la oportunidad para que el testimonio del evangelio penetrara en su cosmovisión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72270, 'spa', 'Compartir generosamente', 'Dar una parte de lo que se posee, impartir o distribuir con generosidad. El énfasis recae en el dar participativo más que en la transferencia total. Juan el Bautista manda compartir la ropa con los necesitados (Lucas 3:11); Pablo desea impartir un don espiritual (Romanos 1:11); el generoso es llamado a compartir con diligencia (Romanos 12:8); y el ladrón debe ahora trabajar para tener qué compartir (Efesios 4:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72271, 'spa', 'Cambio o traslación', 'Cambio fundamental, remoción o transferencia de un estado a otro. En Hebreos describe la transformación del sacerdocio (7:12), la traslación corporal de Enoc al cielo (11:5) y la remoción escatológica de las cosas creadas (12:27). El griego μετάθεσις abarca desde el cambio de posición hasta la sustitución total o la eliminación definitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72273, 'spa', 'Mandar llamar', 'Convocar o enviar por alguien, haciéndolo venir desde otro lugar. El prefijo μετά- transmite movimiento hacia quien llama, distinguiéndolo de un simple llamado. Las cuatro apariciones en el NT se encuentran en Hechos: José convoca a Jacob a Egipto (7:14), Cornelio recibe instrucciones de enviar por Pedro (10:32), Pablo convoca a los ancianos efesios (20:17) y Félix manda llamar a Pablo (24:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72274, 'spa', 'Ser desplazado espiritualmente', 'El participio presente pasivo nominativo masculino plural ''siendo movidos'' describe lo que no debe ocurrir. Las traducciones interlinguas (español ''siendo-movidos,'' alemán ''wegbewegen'') transmiten el peligro de desplazamiento desde una posición firme. Pablo visualiza presiones externas que intentan apartar a los creyentes de la esperanza del evangelio, requiriendo resistencia activa para permanecer firmemente establecidos en la fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72275, 'spa', 'Tomar alimento, comer', 'Participar de alimento, nutrirse, comer una comida. Este sentido concreto aparece tres veces: en Hch 2:46 la comunidad primitiva de Jerusalén compartía alimento (μετελάμβανον τροφῆς) con alegría y sencillez de corazón, y en Hch 27:33-34 Pablo insta dos veces a los pasajeros del naufragio a μεταλαβεῖν τροφῆς para su supervivencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72276, 'spa', 'Recibir, participar de', 'Recibir una porción de algo, participar en ello u obtenerlo, generalmente algo abstracto: una oportunidad, una bendición o la disciplina divina. En Hch 24:25 Félix despide a Pablo diciendo que lo llamará en momento oportuno; en 2 Ti 2:6 el agricultor debe ser primero en participar de la cosecha; en He 12:10 Dios disciplina para nuestro bien.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72281, 'spa', 'Recepción con gratitud', 'La forma acusativa femenina singular funciona con ''para recibir'' (εἰς μετάληψιν), expresando propósito. Las traducciones interlinguas (español ''participación,'' alemán ''Genuss'') enfatizan el acto receptivo de participar de lo que Dios provee. Pablo defiende la bondad de la creación contra la devaluación protognóstica de la materia, insistiendo en que los creyentes reciban los dones de Dios con gratitud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72283, 'spa', 'Lamentar, sentir remordimiento', 'Experimentar pesar o remordimiento después de una acción, implicando un cambio de sentimiento más que el arrepentimiento profundo (μετάνοια) que transforma la voluntad y la dirección de vida. En Mateo 21:29 y 21:32, la palabra describe al hijo que inicialmente se negó a trabajar pero después lamentó su rechazo y obedeció, en contraste con los líderes religiosos que no sintieron tal pesar. El remordimiento de Judas en Mateo 27:3 ilustra cómo este pesar emocional puede conducir a la desesperación en lugar de a la verdadera restauración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72289, 'spa', 'Transformar o transfigurar', 'Ser transformado o transfigurado, describiendo un cambio profundo de forma que revela exteriormente la realidad interior. En Mateo 17:2 y Marcos 9:2, la gloria divina de Jesús resplandece a través de su apariencia humana en el monte. En Romanos 12:2 y 2 Corintios 3:18, los creyentes son progresivamente transformados por la acción del Espíritu, pasando de gloria en gloria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72290, 'spa', 'Experimentar un cambio decisivo de mente y corazon, volviendose del pecado hacia', 'Experimentar un cambio decisivo de mente y corazon, volviendose del pecado hacia Dios. Inaugura la predicacion tanto de Juan el Bautista (Mt 3:2) como de Jesus (Mt 4:17), y se convierte en el llamado apostolico en Pentecostes (Hch 2:38; 3:19). En Apocalipsis, el Cristo resucitado lo exige a cinco iglesias (Ap 2:5, 16, 21; 3:3, 19), demostrando que el arrepentimiento no es un acto unico sino una postura continua ante Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72306, 'spa', 'Un cambio profundo de mente y corazón que resulta en apartarse del pecado y volv', 'Un cambio profundo de mente y corazón que resulta en apartarse del pecado y volverse a Dios, abarcando tanto la reorientación interior como la transformación exterior. Central en la predicación de Juan el Bautista (Mt 3:8, 11; Mr 1:4; Lc 3:3) y en la proclamación apostólica (Hch 5:31; 11:18). La etimología griega μετά + νοῦς pone en primer plano lo cognitivo más que el español «arrepentimiento» o el alemán «Buße», que se inclinan hacia la contrición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72308, 'spa', 'Entre (espacial/relacional)', 'Indica posicion espacial o separacion relacional entre dos entidades. Se emplea para el espacio entre personas (Mt 18:15, ''entre tu y el''), entre figuras historicas (Mt 23:35, entre Abel y Zacarias), y el abismo infranqueable entre el seno de Abraham y el Hades (Lc 16:26). El espanol ''entre'' captura fielmente este sentido espacial-relacional central.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72309, 'spa', 'Siguiente, intermedio', 'Senala al elemento que sigue en una secuencia temporal, el que esta en medio de dos momentos. En Hch 13:42, el pueblo pide a Pablo que hable de nuevo ''el sabado siguiente'' (to metaxu sabbaton), el sabado que se encuentra entre este y el proximo. El espanol ''siguiente'' capta este matiz secuencial derivado del contexto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72310, 'spa', 'Entre tanto, mientras', 'Uso puramente temporal y adverbial que significa ''mientras tanto'' o ''en el tiempo intermedio''. En Jn 4:31, mientras Jesus conversa con la mujer samaritana, los discipulos le instan ''entre tanto'' (en to metaxu) a que coma. El espanol ''entre tanto'' conserva la metafora espacial incrustada en el uso temporal, literalmente ''entre tanto tiempo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72311, 'spa', 'Mandar llamar, convocar', 'Enviar un mensajero para buscar o convocar a una persona, solicitando su presencia por medio de un intermediario. Circunscrito enteramente a Hechos en el NT, este verbo describe el proceso formal de mandar a buscar a alguien en lugar de ir uno mismo. El centurion Cornelio manda llamar a Pedro tres veces en la narrativa (Hch 10:5, 22, 29), y el termino reaparece en el relato posterior de Pedro (Hch 11:13) y en escenas similares de convocatoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72319, 'spa', 'Transformar o pervertir', 'Dar vuelta, transformar o cambiar de manera fundamental, con matices que van desde la transformación neutra hasta la perversión deliberada. Hechos 2:20 lo usa para la inversión cósmica (sol en tinieblas), Gálatas 1:7 para la corrupción doctrinal y Santiago 4:9 para el cambio emocional (gozo en dolor). El griego μεταστρέφω abarca tanto el sentido neutro como el peyorativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72320, 'spa', 'Disfrazar o transformar', 'Cambiar la forma exterior, disfrazar o aplicar figuradamente. Abarca desde la figura retórica (1 Co 4:6, donde Pablo «aplicó» las cosas a sí mismo como ilustración) hasta la mascarada engañosa (2 Co 11:13-15, donde falsos apóstoles y Satanás «se disfrazan»), e incluso la transformación escatológica (Fil 3:21, donde Cristo «transformará» nuestros cuerpos humildes).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72321, 'spa', 'Trasladar, transportar', 'Trasladar o transportar físicamente de un lugar a otro, usado para reubicación corporal o traslación divina. Dios ''trasladó'' a Enoc para que no viera la muerte (Hebreos 11:5), y los restos de los patriarcas ''fueron trasladados'' a Siquem (Hechos 7:16). Este sentido de transferencia física constituye el uso más concreto y primario del verbo en el Nuevo Testamento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72322, 'spa', 'Cambiar, apartarse, desertar', 'Cambiar de lealtad o posición, apartarse o desertar, describiendo un desplazamiento de una fidelidad o estado a otro. En Gálatas 1:6, Pablo se asombra de que los gálatas ''se estén pasando'' tan rápidamente a un evangelio diferente. Hebreos 7:12 lo emplea para el cambio de sacerdocio que exige un cambio correspondiente en la ley. El matiz es de un movimiento voluntario y deliberado de abandono.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72325, 'spa', 'Pervertir, distorsionar, torcer', 'Pervertir o distorsionar, torciendo algo hasta convertirlo en su opuesto, especialmente al corromper la verdad divina. En Judas 1:4, infiltrados impíos están ''pervirtiendo'' la gracia de Dios convirtiéndola en libertinaje. El contexto exige un sentido más fuerte que un simple ''cambiar'': se trata de una distorsión deliberada que transforma la gracia en su antítesis.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72327, 'spa', 'Posterioridad temporal', 'La forma adverbial marca secuencia temporal: ''después, cuando quiso heredar la bendición.'' Las traducciones interlinguas (español ''después,'' alemán ''danach'') enfatizan la separación cronológica entre la elección de Esaú y su arrepentimiento, subrayando la trágica irreversibilidad de despreciar los dones de Dios: la bendición ya había sido cedida y no podía recuperarse.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72328, 'spa', 'Participar, tener parte', 'Tener parte en algo o participar de ello, con enfasis en la recepcion de una porcion de lo que se posee en comun. Se usa para participar de alimentos y bebidas, tanto del pan literal (1 Co 10:17) como de la mesa de los demonios (1 Co 10:21), para compartir el servicio sacerdotal (Heb 7:13), para recibir leche en lugar de alimento solido en la ensenanza (Heb 5:13), y de manera aun mas impactante, para describir a Cristo participando de carne y sangre a fin de vencer la muerte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72335, 'spa', 'Ansiedad e inquietud', 'El imperativo presente medio/pasivo de segunda persona plural ''no andéis ansiosos'' prohíbe la preocupación continua. Las traducciones interlinguas (español ''andéis-ansiosos,'' francés ''s''inquiéter'') transmiten el estado mental inquieto de la ansiedad. Jesús lo prohíbe por ser incompatible con la confianza en la provisión del Padre, llamando a buscar primero el reino de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72336, 'spa', 'Deportación babilónica', 'Deportación o exilio, específicamente el reasentamiento forzoso de Judá en Babilonia bajo Nabucodonosor. El vocablo conlleva el peso de la catástrofe nacional y el juicio divino. Las cuatro apariciones en el NT se hallan en Mateo 1:11-17, donde el exilio babilónico sirve como punto de inflexión que estructura la genealogía de Jesús en tres grandes períodos históricos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72338, 'spa', 'Asociación y comunión', 'La única aparición neotestamentaria se encuentra en el llamado de Pablo contra el yugo desigual con los incrédulos. Las traducciones interlinguas enfatizan la asociación y participación, con el alemán ''Gemeinschaft'' resaltando la dimensión de comunión. En 2 Corintios 6:14, Pablo presupone que la verdadera asociación requiere valores compartidos, haciendo imposible la alianza entre justicia e iniquidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72339, 'spa', 'Partícipe espiritual', 'Partícipe, quien comparte en una realidad espiritual o un llamamiento, enfatizando la participación en algo recibido de Dios. Hebreos emplea este sentido repetidamente: partícipes de un llamamiento celestial (3:1), de Cristo (3:14), del Espíritu Santo (6:4) y de la disciplina divina (12:8). Tanto el español partícipes como el alemán Teilhaber resaltan la idea de recibir parte en algo superior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72340, 'spa', 'Compañero o asociado', 'Compañero, prójimo cercano, subrayando la cercanía relacional y el estatus compartido más que la mera posesión en común. En Heb 1:9 (citando Sal 45:7), el Hijo es ungido por encima de sus compañeros (μετόχους), quienes comparten su dignidad real. El español compañeros desplaza el énfasis de la participación abstracta hacia la asociación personal y la comunión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72341, 'spa', 'Socio comercial', 'Socio de negocios, asociado en una empresa compartida: el uso más concreto y comercial. En Lucas 5:7, Jacobo y Juan son llamados μέτοχοι de Simón en el oficio pesquero. Tanto el español compañeros como el alemán Teilhaber encajan naturalmente aquí. El contexto de barcas y faenas compartidas ancla este sentido firmemente en la asociación económica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72342, 'spa', 'Medir, asignar o determinar cantidad o extensión en voz activa', 'Medir, asignar o determinar cantidad o extensión en voz activa. Abarca la enseñanza de Jesús sobre el juicio recíproco: ''con la medida con que medís, os será medido'' (Mt 7:2; Mr 4:24; Lc 6:38), donde la voz activa expresa el acto humano de juzgar a otros. También se usa para medición literal: el ángel midiendo el templo de Dios en Ap 11:1 y la crítica de Pablo a quienes se miden a sí mismos por sí mismos (2 Co 10:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72345, 'spa', 'Ser medido, recibir medida de vuelta', 'Ser medido, recibir medida de vuelta: la voz pasiva de μετρέω que expresa la retribución divina o recíproca. Atestiguado en el futuro pasivo μετρηθήσεται (''os será medido'') en Mt 7:2 y Mr 4:24. Esta voz pasiva completa el proverbio de reciprocidad de Jesús: la norma que aplicas a otros se te aplicará a ti. La pasiva transforma la medición de un acto humano en una respuesta divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72348, 'spa', 'Medida de líquidos', 'El único uso neotestamentario describe las tinajas de agua en Caná que sirvieron de escenario para la primera señal de Jesús. El detalle sobre la capacidad (dos o tres medidas cada una) resalta la abundancia del milagro: Jesús proveyó una cantidad enorme de vino superior, aproximadamente entre 420 y 630 litros en total.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72349, 'spa', 'Trato moderado y compasivo', 'En Hebreos 5:2, este verbo define la disposición pastoral del sumo sacerdote hacia quienes yerran por ignorancia o se desvían. El contexto enfatiza que tal trato gentil nace de la propia experiencia de debilidad del sacerdote, permitiéndole responder con compasión equilibrada en lugar de ira o indiferencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72350, 'spa', 'Grado moderado', 'Lucas usa este adverbio en Hechos 20:12 para describir el consuelo de la congregación tras la restauración de Eutico. Las glosas interlingüísticas revelan opciones interpretativas: poco sugiere consuelo modesto, mientras que el contexto del rescate milagroso sugiere un alivio apropiado y proporcionado más que simplemente escaso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72351, 'spa', 'Medida', 'Medida: un patrón o instrumento por el cual se determina la cantidad, extensión o proporción. Se usa para el principio recíproco del juicio divino (Mt 7:2; Mc 4:24; Lc 6:38, donde una ''buena medida, apretada, remecida y rebosante'' será devuelta), para el alcance divinamente asignado del ministerio (2 Co 10:13; Ef 4:7), y para la plena estatura de Cristo como meta hacia la cual crecen los creyentes (Ef 4:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72354, 'spa', 'Frente (parte de cabeza)', 'La superficie frontal de la cabeza humana por encima de los ojos, utilizada en Apocalipsis como el lugar donde se inscriben sellos, marcas o nombres. Las ocho apariciones neotestamentarias se concentran en Apocalipsis, donde la frente funciona como marca visible de lealtad, ya sea a Dios (Ap 7:3, 14:1) o a la bestia (Ap 13:16, 14:9, 17:5). La traduccion es uniforme en las distintas lenguas: espanol ''frente'', aleman ''Stirn'', frances ''front''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72356, 'spa', 'Marcador de límite espacial o temporal que indica el punto hasta el cual se exti', 'Marcador de límite espacial o temporal que indica el punto hasta el cual se extiende una acción, estado o condición. Los usos temporales predominan: ''hasta el día de hoy'' (Mt 28:15), ''hasta Juan'' (Lc 16:16), ''hasta el día de Cristo'' (Fil 1:10; 2:16), ''hasta que todos lleguemos a la unidad'' (Ef 4:13). El sentido espacial aparece en ''hasta el Hades'' (Mt 11:23) y en el extraordinario uso cristológico ''obediente hasta la muerte'' (Fil 2:8), donde μέχρι marca un extremo culminante más que un mero punto final.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72357, 'spa', 'negación subjetiva', 'Negación usada con modos no indicativos, en cláusulas condicionales y en contextos donde la negación es hipotética o contingente — ''no''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72359, 'spa', 'negación prohibitiva', 'Negación usada para expresar prohibición o mandato negativo, especialmente con subjuntivo o imperativo — ''no'' (en el sentido de ''no hagas'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72379, 'spa', 'ni, y no', 'Uso conjuntivo principal: ''ni'', ''y no'', enlazando una cláusula negativa con una negación precedente para extender la prohibición. Función dominante en el NT, frecuente en las instrucciones de Jesús: «No os afanéis por vuestra vida, ni (μηδέ) por vuestro cuerpo» (Mt 6:25); «No deis lo santo a los perros, ni (μηδέ) echéis vuestras perlas» (Mt 7:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72380, 'spa', 'ni (serie paulina)', 'La misma función conjuntiva ''ni'' en un pasaje paulino concentrado: 1 Co 10:7-10, donde Pablo encadena advertencias de la historia de Israel: «No os hagáis idólatras... ni (μηδέ) forniquemos... ni (μηδέ) tentemos a Cristo... ni (μηδέ) murmuréis.» La acumulación en una sola unidad parenética con tipología veterotestamentaria le confiere carácter propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72381, 'spa', 'ni siquiera', 'Uso adverbial intensificador: ''ni siquiera'', enfatizando lo extremo de una situación. En Mr 2:2, se reunieron tantos que «ni siquiera (μηδέ) el espacio junto a la puerta» podía contenerlos. En Mr 3:20, la multitud era tal que «ni siquiera (μηδέ) podían comer pan». El español ''ni siquiera'' explicita esta fuerza escalar e intensificadora, distinguiéndola del simple enlace conjuntivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72383, 'spa', 'nada', 'Uso sustantivo referido a cosas: ''nada, ninguna cosa'' (37 apariciones). El neutro μηδέν funciona como pronombre que niega la existencia o relevancia de cualquier cosa o asunto: «nada llevéis para el camino» (Mr 6:8), «sin esperar nada a cambio» (Lc 6:35), «por nada estéis afanosos» (Fil 4:6). El español ''nada'' captura fielmente esta negación referida a cosas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72384, 'spa', 'nadie, ninguno', 'Uso sustantivo referido a personas: ''nadie, ninguno, ni uno solo'' (49 apariciones). Es la función más frecuente, presente en prohibiciones («no lo digas a nadie», Mt 8:4; Mr 1:44), advertencias («que nadie os engañe», 2 Ts 2:3) y exhortaciones generales. El español ''nadie'' traduce con exactitud esta negación pronominal referida a personas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72390, 'spa', 'ningún, ninguna (adjetivo)', 'Uso adjetival que modifica directamente un sustantivo: ''ningún, ninguna'', como determinante que niega al nombre que acompaña (5 apariciones). Ejemplos: «que nada os falte en ningún don» (1 Co 1:7), «que nadie os engañe de ninguna manera» (2 Ts 2:3, μηδείς modifica τρόπος), «no dar ninguna ocasión al adversario» (1 Ti 5:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72401, 'spa', 'Negación temporal absoluta', 'Pablo emplea esta negación temporal enfática en 2 Timoteo 3:7 para caracterizar el trágico estado perpetuo de quienes aprenden continuamente pero jamás alcanzan el verdadero conocimiento de la verdad. El contexto retrata un ciclo frustrante: actividad permanente de aprendizaje con resultado nulo, donde el nunca subraya un fracaso que se extiende a todo momento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72402, 'spa', 'Negación temporal prospectiva', 'En Hebreos 11:7, este adverbio destaca la notable fe de Noé: respondió a la advertencia divina acerca de cosas aún no vistas. La expresión subraya la esencia de la fe: Noé construyó el arca antes de que existiera evidencia alguna del juicio venidero, actuando solo por la palabra de Dios cuando el diluvio era todavía futuro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72403, 'spa', 'Pueblo de Media', 'Lucas incluye a los medos en su lista exhaustiva de judíos de la diáspora y prosélitos reunidos en Jerusalén para Pentecostés. La evidencia multilingüe preserva la designación étnica mediante transliteración o traducción directa. Los medos representan la frontera oriental de la dispersión judía, pues el territorio medo fue destino de exilio de los israelitas del norte siglos antes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72404, 'spa', 'Adverbio temporal negativo que significa «ya no, no más», indicando el cese de u', 'Adverbio temporal negativo que significa «ya no, no más», indicando el cese de un estado previo. Usado en la narrativa (Mr 1:45, «ya no podía entrar abiertamente en la ciudad»; Mr 2:2) y en la instrucción exhortatoria (Ef 4:14, 17, 28). La evidencia multilingüe — español «ya no», francés «ne plus», alemán «nicht mehr» — confirma uniformemente un sentido único.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72409, 'spa', 'Dimensión lineal', 'La dimensión espacial lineal que mide la extensión de un extremo a otro. En Efesios 3:18 es una de las cuatro dimensiones empleadas para expresar el alcance inconmensurable del amor de Cristo. En Apocalipsis 21:16 (dos veces) describe la dimensión medida de la Nueva Jerusalén. El griego μῆκος es un término geométrico puro, sin carga metafórica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72410, 'spa', 'Crecimiento misterioso', 'Mark 4:27 emplea este verbo en la parábola de Jesús sobre el crecimiento misterioso del reino. La evidencia interlingüística destaca uniformemente la dimensión de crecimiento, especialmente adecuada al contexto agrícola. La parábola subraya la cualidad automática y orgánica del crecimiento del reino: la semilla se alarga y desarrolla por poder divino, independientemente de la comprensión o el esfuerzo humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72411, 'spa', 'Prenda de piel ovina', 'Hebrews 11:37 incluye las pieles de oveja en su sobrecogedora lista de padecimientos sufridos por los fieles testigos de Dios. El contexto las empareja con pieles de cabra como emblema de privación extrema y rechazo social: estos héroes de la fe quedaron reducidos a vestir pieles de animales, errando como marginados. La imagen evoca el tosco manto de Elías y la tradición profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72412, 'spa', 'Afirmación solemne enfática', 'En Hebrews 6:14, esta partícula enfática refuerza el juramento de Dios a Abraham, intensificando la certeza de la promesa. El contexto subraya la naturaleza inquebrantable de la palabra divina: como Dios no podía jurar por nada superior, juró por sí mismo, añadiendo esta partícula enfática para recalcar la absoluta fiabilidad de su compromiso con Abraham y su descendencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72413, 'spa', 'Unidad calendárica de aproximadamente treinta días, que sirve para marcar duraci', 'Unidad calendárica de aproximadamente treinta días, que sirve para marcar duraciones, fechas específicas dentro de una secuencia y períodos de tiempo proféticos. La narración lucana de la infancia la emplea para seguir los embarazos de Elisabet y María con cuidadosa precisión: cinco meses de reclusión, el sexto mes de la visitación, tres meses de la estancia de María (Lc 1:24, 26, 36, 56). Hechos mide los períodos del ministerio de Pablo en meses. En Apocalipsis los meses se transforman en unidades proféticas: los cuarenta y dos meses de la bestia evocan la tribulación de Daniel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72416, 'spa', 'Revelar o informar', 'Divulgar, informar o dar a conocer algo oculto o previamente desconocido, ya sea mediante testimonio formal, advertencia o revelación. En Lucas 20:37, Moisés «indica» la naturaleza de Dios en la zarza ardiente; en Juan 11:57 las autoridades buscan quien delate a Jesús; en Hechos 23:30 se informa de una conspiración; y en 1 Corintios 10:28 alguien advierte sobre comida sacrificada a ídolos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72417, 'spa', 'Temor de consecuencia', 'En Matthew 25:9, las vírgenes prudentes emplean esta conjunción para articular su temor sobre compartir el aceite. El contexto implica un cálculo prudente: compartir arriesgaría dejar a todas en oscuridad cuando llegue el esposo. La expresión comunica aprensión genuina sobre la consecuencia de una generosidad imprudente, pues la escasez resultante afectaría a ambos grupos por igual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72419, 'spa', 'Muslo como poder real', 'La visión de Juan en Apocalipsis 19:16 coloca el título supremo en el muslo de Cristo, lugar de poder real y fuerza militar. La evidencia interlingüística identifica consistentemente esta ubicación anatómica. La imagen evoca el Salmo 45:3, donde al guerrero poderoso se le dice que ciña su espada al muslo. La ubicación del título enfatiza la autoridad real y el poder conquistador de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72420, 'spa', 'Conjuncion correlativa negativa que se emplea como μήτε', 'Conjuncion correlativa negativa que se emplea como μήτε...μήτε (''ni...ni'') para excluir sistematicamente alternativas. Central en la prohibicion de Jesus sobre los juramentos: ''ni por el cielo, ni por la tierra, ni por Jerusalen'' (Mt 5:34-36), eco en Santiago 5:12. Pablo usa la construccion pareada para enumerar lo que no puede separar a los creyentes del amor divino (Ro 8:38-39) y para relativizar la circuncision (Ga 6:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72421, 'spa', 'madre', 'Sentido primario: madre como progenitora biológica o social, abarcando 77 de 84 apariciones. Cubre la relación de una mujer con su hijo en la narrativa (Mt 2:11, «el niño con María su madre»), el discurso legal (Mt 15:4, «honra a tu padre y a tu madre») y la declaración teológica (Gá 4:26, «la Jerusalén de arriba es nuestra madre»).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72422, 'spa', 'de madre (origen)', 'Construcción preposicional que significa ''de su madre'' o ''desde su madre'', presente 5 veces en el modismo «desde el vientre de su madre» para expresar ''desde el nacimiento'' o ''congénitamente'' (Mt 19:12, eunucos de nacimiento; Hch 3:2, cojo de nacimiento; Gá 1:15, apartado desde antes de nacer). El genitivo señala origen o procedencia, no relación identitaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72424, 'spa', 'madres (plural)', 'La forma plural ''madres'', usada en Mr 10:30 (Jesús promete el ciento por uno en madres, hermanos y hermanas en la comunidad creyente) y 1 Ti 5:2 (tratar a las mujeres mayores como a madres). Estos pasajes extienden metafóricamente el parentesco biológico a la comunidad de fe, ampliando el término más allá del vínculo familiar inmediato.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72425, 'spa', 'Partícula interrogativa que introduce preguntas que esperan una respuesta negati', 'Partícula interrogativa que introduce preguntas que esperan una respuesta negativa, funcionando como marcador de negación retórica o duda vacilante. En Mt 12:23 la multitud se pregunta con incredulidad si Jesús podría ser el Hijo de David. En la Última Cena cada discípulo pregunta ''¿Acaso soy yo, Señor?'' (Mt 26:22, 25). La mujer samaritana la usa para expresar una esperanza cautelosa: ''¿No será este el Cristo?'' (Jn 4:29). El español ''acaso'' y ''¿no será que...?'' reflejan bien este tono de interrogación con expectativa negativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72431, 'spa', 'Comparación a fortiori', 'Pablo despliega esta partícula comparativa en 1 Corintios 6:3 para avanzar su argumento contra los creyentes que llevan disputas a tribunales seculares. Las glosas interlingüísticas expresan uniformemente escalamiento. La lógica se mueve de la dignidad mayor (juzgar ángeles) a la aplicación menor (asuntos cotidianos): si los creyentes son competentes para el juicio escatológico mayor, con mayor razón lo serán para lo menor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72433, 'spa', 'Matricida', 'Pablo incluye a los matricidas en su lista de vicios en 1 Timoteo 1:9, ejemplificando a las personas inicuas y rebeldes para quienes fue dada la ley. La evidencia interlingüística identifica uniformemente a quienes golpean o matan a sus madres. El término aparece emparejado con los parricidas, subrayando las violaciones al quinto mandamiento. Tales crímenes representaban la inversión completa del honor familiar debido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72434, 'spa', 'Contaminar o profanar', 'Manchar, contaminar o hacer impuro, ya sea en el ámbito ceremonial, moral o espiritual. Las autoridades judías evitan el pretorio para no contraer impureza ritual antes de la Pascua (Jn 18:28). Pablo extiende el concepto al interior de la persona: la mente y la conciencia contaminadas hacen que todo resulte impuro (Tit 1:15). Hebreos advierte contra una raíz de amargura que contamina a la comunidad (Heb 12:15), y Judas denuncia a quienes profanan la carne (Jud 1:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72435, 'spa', 'Contaminación mundana', 'En 2 Pedro 2:20 se emplea la forma plural para describir las influencias corruptoras del mundo de las cuales los conversos han escapado. El contexto advierte sobre falsos maestros que, tras escapar de las contaminaciones del mundo mediante Cristo, se enredan de nuevo y son vencidos. El término subraya la naturaleza poluyente y contaminante de las corrupciones mundanas frente a la santidad en Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72436, 'spa', 'Impureza moral', 'En 2 Pedro 2:10 se usa este término para caracterizar la corrupción que impulsa a los falsos maestros: andan en concupiscencia contaminante. La frase ''concupiscencia de impureza'' sugiere no meramente actos lujuriosos sino un deseo caracterizado por su cualidad contaminante y poluyente. Tal impureza representa lo opuesto a la santidad a la que los creyentes son llamados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72437, 'spa', 'Mezcla de sustancias', 'En Juan 19:39, Nicodemo trae una cuantiosa mezcla de mirra y áloes para la sepultura de Jesús. La evidencia interlingüística la traduce consistentemente como mezcla o compuesto. La extraordinaria cantidad, alrededor de setenta y cinco libras, y la costosidad de los ingredientes señalan tanto la devoción de Nicodemo como la honra debida a Jesús. La mezcla representa la combinación de especias aromáticas en proporciones dignas de un entierro real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72438, 'spa', 'Mezclar sustancias', 'Mezclar, combinar o fundir una sustancia con otra, ya sean líquidos, sólidos o elementos simbólicos. En Mateo 27:34 se mezcla vino con hiel como bebida amarga para Jesús. Lucas 13:1 lo emplea de manera figurada y sombría para describir cómo Pilato mezcló la sangre de los galileos con sus sacrificios. En Apocalipsis aparece en imágenes cósmicas: fuego mezclado con sangre (Ap 8:7) y un mar de vidrio mezclado con fuego (Ap 15:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72439, 'spa', 'Un poco de tiempo (adverbio temporal/cuantitativo)', 'Un poco de tiempo (adverbio temporal/cuantitativo). El acusativo neutro μικρόν funciona adverbialmente con el sentido de ''un poco'' o ''un breve tiempo''. Se concentra en el Discurso de Despedida joanino (Jn 7:33; 13:33; 14:19; 16:16-19), donde Jesus habla de su partida y retorno inminentes. Tambien aparece en los Sinopticos para duraciones breves (Mt 26:39, 73; Mr 14:35, 70).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72440, 'spa', 'Los pequenos (sustantivado', 'Los pequenos (sustantivado: personas humildes o insignificantes). El plural sustantivado ''los pequenos'' (οἱ μικροί, τῶν μικρῶν) designa a los miembros humildes, vulnerables o aparentemente insignificantes de la comunidad de fe. Jesus advierte contra despreciar a ''estos pequenos'' (Mt 18:10) y declara que hacer tropezar a uno de ellos merece una piedra de molino al cuello (Mt 18:6; Mr 9:42).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72441, 'spa', 'Pequeno en tamano o grado', 'Pequeno en tamano o grado. Sentido adjetival basico que denota tamano fisico reducido o bajo grado. La semilla de mostaza es la ''mas pequena'' de todas las semillas (Mt 13:32; Mr 4:31). Juan el Bautista es informado de que el ''menor'' en el reino es mayor que el (Mt 11:11; Lc 7:28). Santiago el ''menor'' se distingue del otro Santiago (Mr 15:40).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72447, 'spa', 'Ciudad de Mileto', 'La antigua ciudad griega de Mileto en Caria (Asia Menor occidental), un puerto significativo en los viajes misioneros de Pablo. Hechos 20:15, 17 registran la parada de Pablo allí y su emotivo encuentro con los ancianos de Éfeso. 2 Timoteo 4:20 menciona que Trófimo fue dejado enfermo en ese lugar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72448, 'spa', 'Medida de distancia', 'En Mateo 5:41, Jesús emplea esta medida de distancia dentro de su ética radical de generosidad amorosa. La evidencia interlingüística la identifica uniformemente como unidad de medida. El contexto alude al derecho legal de los soldados romanos de obligar a los civiles a cargar su equipo por una milla. Jesús transforma este servicio forzado en discipulado voluntario: en lugar de un cumplimiento resentido del mínimo, propone una generosidad que va más allá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72449, 'spa', 'Imitar deliberadamente', 'Moldear deliberadamente la propia conducta según el ejemplo de otra persona, ya sea en sentido positivo o negativo. Pablo invoca este sentido cuando dice a los tesalonicenses que imiten su trabajo autosustentado (2 Tes 3:7, 9), y Hebreos 13:7 urge a imitar la fe de los líderes ya fallecidos. En 3 Juan 1:11 el mismo verbo advierte contra copiar lo malo, lo que demuestra que la palabra es moralmente neutra: el objeto imitado determina la calidad moral del acto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72450, 'spa', 'Imitador devoto', 'Quien deliberadamente sigue y reproduce el ejemplo, la conducta o el modelo de otro. Pablo emplea este término para establecer cadenas de imitación: los creyentes imitan a Pablo, quien imita a Cristo (1 Cor 4:16; 11:1), y en última instancia imitan a Dios mismo (Ef 5:1). Los tesalonicenses son elogiados por convertirse en imitadores de los apóstoles y del Señor al recibir la palabra con gozo pese a la aflicción (1 Tes 1:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72452, 'spa', 'Recordar activamente, rememorar o tener presente a una persona, un evento o una ', 'Recordar activamente, rememorar o tener presente a una persona, un evento o una promesa divina. Pedro recordando la predicción de Jesús (Mt 26:75), Dios acordándose de su misericordia hacia la descendencia de Abraham (Lc 1:54, 72) y la instrucción de Jesús sobre recordar ante el altar (Mt 5:23) anclan veintiún ocurrencias. El español «acordarse» y el alemán «gedenket» confirman la recuperación mental deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72461, 'spa', 'Ser recordado o traído a la memoria en construcción pasiva, a menudo como pasivo', 'Ser recordado o traído a la memoria en construcción pasiva, a menudo como pasivo divino donde Dios es el agente implícito. Las oraciones de Cornelio «fueron recordadas» delante de Dios (Hch 10:31) y la gran Babilonia «fue recordada» ante Dios para recibir juicio (Ap 16:19) — solo dos ocurrencias, pero teológicamente ricas. El español «fue recordada» y «fueron recordadas» marcan esta voz con claridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72466, 'spa', 'Odiar, aborrecer, detestar', 'Odiar, aborrecer, detestar. Hostilidad activa e intensa o aversion hacia una persona, grupo o conducta. Abarca toda la gama emocional, desde la animosidad personal (Mt 5:43-44, ''amad a vuestros enemigos'') hasta el odio del mundo hacia Cristo y sus seguidores (Jn 15:18-25; 1 Jn 3:13). El espanol alterna entre ''aborrecer'' (que implica repulsion moral) y ''odiar'', reflejando matices dentro de este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72468, 'spa', 'Ser odiado, ser aborrecido', 'Ser odiado, ser aborrecido. La experiencia pasiva de ser odiado, especialmente como marca de un discipulado fiel. Jesus advierte a sus seguidores: ''sereis odiados de todas las naciones por causa de mi nombre'' (Mt 24:9; Mr 13:13; Lc 21:17). El paso de activo a pasivo reenmarca el odio como algo que se soporta, no que se ejerce. Apocalipsis 18:2 extiende esto a Babilonia convertida en lugar ''aborrecido''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72483, 'spa', 'Amar menos, desestimar comparativamente', 'Amar menos, desestimar comparativamente. Modismo comparativo semitico donde ''odiar'' significa amar menos o dar menor prioridad en comparacion. Genesis 29:31 (LXX μισέω por el hebreo שָׂנֵא) y Lucas 14:26 proporcionan el trasfondo clasico: Jacob ''aborrecia'' a Lea significa que la amaba menos que a Raquel. Este uso no emocional es esencial para interpretar las exigencias radicales de Jesus sobre el discipulado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72488, 'spa', 'Recompensa o retribución', 'La recompensa, retribución o pago que sigue a la conducta, ya sea como castigo por la desobediencia o como galardón por la fidelidad. Hebreos emplea μισθαποδοσία para ambos casos: la justa penalidad por violar la ley (2:2), la gran recompensa por la fe perseverante (10:35) y el galardón futuro que Moisés anticipaba (11:26). El término es moralmente neutro en cuanto a su valencia, pero subraya la certeza de la consecuencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72489, 'spa', 'Remunerador divino', 'En Hebreos 11:6 se declara que quien se acerca a Dios debe creer que Él existe y que recompensa a quienes le buscan. La evidencia interlingüística lo traduce consistentemente como remunerador o galardonador. Esta caracterización de Dios se opone tanto al deísmo, un Dios que existe pero no interviene, como al legalismo, la recompensa ganada por mérito propio. Presenta más bien a un Dios que libremente galardona la búsqueda diligente de comunión con Él.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72490, 'spa', 'Jornalero asalariado', 'Trabajador contratado o jornalero que recibe un salario, ocupando una posición social entre el esclavo y el miembro de la familia. En Lucas 15:17, 19, 21 (la parábola del hijo pródigo), μίσθιος representa el estatus que el hijo espera alcanzar: mejor que la miseria, pero inferior a la condición de hijo. El término enfatiza la relación laboral basada en el salario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72491, 'spa', 'El sentido dominante', 'El sentido dominante: recompensa o galardón, ya sea celestial o escatológico, otorgado por Dios en respuesta a la fidelidad, la justicia o el sufrimiento. Jesús lo emplea repetidamente en el Sermón del Monte (Mt 5:12, 46; 6:1-6) y Pablo lo invoca para la labor apostólica (1 Co 3:8, 14). Las glosas multilingües convergen en vocabulario de recompensa — español «galardón/recompensa», francés «salaire» en su acepción antigua de «recompensa».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72492, 'spa', 'El sentido económico concreto', 'El sentido económico concreto: salario o paga ganados por el trabajo o servicio. El obrero es digno de su μισθός (Lc 10:7, 1 Ti 5:18), el dueño de la viña liquida el μισθός al final del día (Mt 20:8) y Pablo dice que al que trabaja su μισθός se le cuenta como deuda, no como regalo (Ro 4:4). El español «salario» marca esto como un pago transaccional y contractual, distinto de la recompensa gratuita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72495, 'spa', 'Un uso adverbial o de propósito poco frecuente que significa «por paga» o «por a', 'Un uso adverbial o de propósito poco frecuente que significa «por paga» o «por afán de lucro», que aparece solo en Judas 1:11 donde los falsos maestros se precipitan al error de Balaam «por paga». La construcción preposicional destaca el motivo mercenario más que el pago en sí. Las glosas multilingües — español «por paga», alemán «für Lohn» — confirman el encuadre de propósito que distingue este uso del sentido nominal habitual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72497, 'spa', 'Vivienda alquilada', 'En Hechos 28:30, Lucas concluye su narrativa con Pablo habitando en su propia casa alquilada en Roma durante dos años. Las traducciones interlingüísticas enfatizan la naturaleza rentada o arrendada de la vivienda. Este detalle indica que Pablo, aunque custodiado, aseguró y pagó su propio alojamiento en lugar de estar confinado en una prisión. Esta situación le permitió recibir a cuantos venían y proclamar el reino de Dios con toda libertad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72498, 'spa', 'Asalariado mercenario', 'Sirviente contratado o trabajador a sueldo, en contraste con quienes tienen un compromiso genuino. Marcos 1:20 menciona de forma neutral a los jornaleros en la barca de Zebedeo. Juan 10:12-13 usa μισθωτός de manera peyorativa para el pastor asalariado que abandona las ovejas en peligro, preocupándose solo por su paga. El término resalta la motivación mercenaria frente al amor o la pertenencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72499, 'spa', 'Ciudad portuaria', 'En Hechos 20:14, Mitilene aparece como un punto de escala en el urgente viaje de Pablo para llegar a Jerusalén antes de Pentecostés. Las traducciones interlingüísticas preservan el nombre propio mediante transliteración. La ciudad servía como puerto natural de pernocta para los barcos que navegaban por la costa de Asia. La precisa anotación geográfica de Lucas refleja su característica atención a los detalles del viaje, documentando el avance sistemático de ciudad en ciudad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72501, 'spa', 'Mina (unidad monetaria)', 'Unidad monetaria antigua de valor considerable pero no extraordinario, equivalente a unas 100 dracmas o aproximadamente cuatro meses de salario de un jornalero. Es un prestamo semitico (cf. hebreo maneh), y las traducciones en diversas lenguas simplemente lo transliteran: espanol ''mina'', frances ''mine'', aleman ''Mine''. Aparece exclusivamente en Lc 19:13-25, en la parabola de Jesus donde diez siervos reciben cada uno una mina para invertirla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72502, 'spa', 'Nombre propio personal', 'Hechos 21:16 presenta a Mnasón como el anfitrión de la delegación de Pablo en Jerusalén. Lucas lo describe como un discípulo antiguo de Chipre, lo que sugiere décadas de fidelidad. La hospitalidad concertada indica planificación y recursos considerables para albergar a toda la comitiva. Su origen chipriota lo vincula con la comunidad misionera temprana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72503, 'spa', 'Recuerdo, mención', 'El acto de recordar o mencionar a alguien, típicamente en oración intercesora. En el uso paulino, μνεία aparece en la fórmula ''haciendo mención de vosotros en mis oraciones'', combinando afecto con hábito litúrgico. Romanos 1:9 y Efesios 1:16 muestran a Pablo asegurando a congregaciones distantes que ocupan sus pensamientos ante Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72506, 'spa', 'Tumba o sepulcro', 'Lugar de sepultura o sepulcro, generalmente una cámara excavada en roca o un monumento para los muertos. En los Evangelios, aparece tanto para los sepulcros donde habitaba el endemoniado gadareno (Marcos 5:3, 5:5; Lucas 8:27) como para la tumba donde fue sepultado Jesús (Lucas 23:53, 24:1). En Hechos 2:29, Pedro hace referencia al sepulcro de David como aún visible en Jerusalén. El vínculo etimológico con la memoria (de μνάομαι) sustenta el sentido original del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72509, 'spa', 'Sepulcro, tumba (lugar de sepultura)', 'Sepulcro, tumba (lugar de sepultura). Sentido principal: un sepulcro o lugar de enterramiento especifico, tipicamente una camara excavada en la roca. El sepulcro de Jose de Arimatea (Mt 27:60), la tumba vacia en la resurreccion (Mt 28:8) y el sepulcro de Lazaro (Jn 11:38) pertenecen a este sentido. El espanol ''sepulcro'' denota un espacio funerario construido, distinto de una simple fosa en el suelo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72510, 'spa', 'Sepulcros, tumbas (sentido colectivo plural)', 'Sepulcros, tumbas (sentido colectivo plural). El sentido plural colectivo: tumbas como lugares asociados con los muertos, la impureza o el peligro espiritual. El endemoniado gadareno habitaba ''entre los sepulcros'' (Mt 8:28; Mr 5:2), y las tumbas ocultas de Lucas 11:44 contaminan a quienes caminan sobre ellas sin saberlo. El plural ''sepulcros/tumbas'' en espanol transmite el tono colectivo y ominoso de estos pasajes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72511, 'spa', 'Monumento conmemorativo', 'Monumento conmemorativo. Sentido poco frecuente de monumento o memorial, mas cercano al origen griego clasico de la palabra como ''recuerdo'' (μνήμη). En Mateo 23:29 Jesus denuncia a quienes ''edifican los monumentos de los profetas''; el espanol ''monumentos'' apunta a la funcion conmemorativa mas que funeraria, evocando el vinculo etimologico con la memoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72512, 'spa', 'Memoria y recuerdo', 'En 2 Pedro 1:15, Pedro muestra su preocupación pastoral de que sus lectores conserven la memoria de verdades esenciales tras su muerte. Su frase sugiere un esfuerzo intencional para garantizar una evocación continua: no la mera capacidad de recordar, sino la práctica activa de traer a la mente estas realidades vitales. Su carta sirve como instrumento de esa memoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72513, 'spa', 'Traer a la memoria, rememorar o mantenerse consciente de algo — ya sean eventos ', 'Traer a la memoria, rememorar o mantenerse consciente de algo — ya sean eventos pasados, las palabras de Jesús o personas que merecen recuerdo continuo. Usado como mandato directo de Jesús («Acordaos de la mujer de Lot», Lc 17:32), como exhortación apostólica a recordar enseñanzas y trabajos (Jn 15:20; 16:4; Hch 20:35; Gá 2:10; 1 Ts 2:9; 2 Ti 2:8), y en Hebreos para recordar tanto el sufrimiento propio pasado (Heb 10:32) como a los creyentes encarcelados que necesitan solidaridad (Heb 13:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72525, 'spa', 'Memorial conmemorativo', 'Un memorial o recordatorio, un acto u ofrenda que hace que alguien sea recordado. En Mateo 26:13 y Marcos 14:9, la unción de la mujer se convierte en un μνημόσυνον perpetuo proclamado junto con el evangelio. En Hechos 10:4, la piedad de Cornelio asciende como memorial ante Dios, asegurando la atención divina. El término griego subraya la función de preservar la memoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72526, 'spa', 'Desposada formalmente', 'Desposada, comprometida formalmente en un vínculo prenupcial legalmente obligatorio. En la ley judía, el desposorio (μνηστεύω) era la primera etapa del matrimonio, con obligaciones legales aunque sin cohabitación. Las tres apariciones neotestamentarias describen el estado de María respecto a José (Mt 1:18; Lc 1:27; 2:5) en el momento de la concepción y el nacimiento de Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72527, 'spa', 'Impedimento del habla', 'Marcos 7:32 presenta a un hombre sordo y con dificultad para hablar, llevado ante Jesús para sanación. La combinación con la sordera sugiere que el problema del habla resultaba de no poder oír ni formar correctamente las palabras. La sanación de Jesús demuestra su autoridad sobre las discapacidades físicas y cumple la promesa profética de Isaías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72528, 'spa', 'Con dificultad, apenas', 'En Lucas 9:39, este adverbio describe la salida violenta y resistida del demonio de su víctima. El padre subraya la presa destructiva del demonio y su renuencia a soltar al muchacho: cuando finalmente se aparta, lo hace apenas, de mala gana y con violencia. La palabra transmite un logro obtenido solo al límite del esfuerzo posible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72529, 'spa', 'Recipiente de medida', 'Almud o cajón, recipiente de medida seca utilizado para grano. En sus tres apariciones (Mt 5:15; Mr 4:21; Lc 11:33), Jesús lo usa como el absurdo escondite de una lámpara, ilustrando que los discípulos no deben ocultar su luz. El griego μόδιος es un préstamo del latín modius, medida estándar de aproximadamente 8,75 litros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72530, 'spa', 'Adúltero (infidelidad espiritual)', 'Usado figuradamente para caracterizar a una generación o pueblo como espiritualmente infiel a Dios, evocando la metáfora profética veterotestamentaria de Israel como esposa infiel. En Mt 12:39 y 16:4 Jesús llama a la generación que busca señales γενεὰ μοιχαλίς (''generación adúltera''); en Mr 8:38 advierte contra la vergüenza ''en esta generación adúltera y pecadora''; y en Stg 4:4 Santiago se dirige a los espiritualmente infieles con este mismo término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72531, 'spa', 'Adúltera (sentido literal)', 'Mujer que comete adulterio literal y físico al violar el pacto matrimonial. Pablo emplea este sentido en su analogía jurídica en Romanos 7:3, argumentando que la mujer casada que vive con otro hombre estando vivo su esposo μοιχαλὶς χρηματίσει (''será llamada adúltera''), pero si su esposo muere, queda libre de esa ley.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72534, 'spa', 'Cometer adulterio', 'Cometer adulterio, específicamente en el contexto de nuevas nupcias ilícitas tras el divorcio. Jesús emplea este verbo para declarar que el hombre que repudia a su mujer y se casa con otra comete adulterio (Mt 19:9; Mr 10:11), e igualmente la mujer que hace lo mismo (Mr 10:12). En Mateo 5:32 se dice que la mujer repudiada injustamente es inducida a cometer adulterio. El término señala de forma directa la ruptura del pacto conyugal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72535, 'spa', 'Infidelidad conyugal', 'El acto de adulterio, infidelidad sexual dentro del matrimonio. Jesús incluye μοιχεία en su catálogo de maldades del corazón que contaminan al ser humano (Mt 15:19; Mr 7:21). Juan 8:3 narra el caso de una mujer sorprendida en el acto mismo. El término designa un pecado sexual que quebranta el pacto conyugal, transgresión de los Diez Mandamientos universalmente reconocida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72536, 'spa', 'Cometer adulterio', 'Cometer adulterio: el sentido estándar de cometer adulterio, abarcando prohibiciones directas (Mt 5:27; Mc 10:19), descripciones de quienes lo cometen (Mt 5:28; Lc 16:18) y reconocimientos confesionales. Las traducciones en todas las lenguas son notablemente uniformes — español ''adulterar,'' francés ''commettre l''adultère'' — reflejando la gravedad moral universal de la infidelidad conyugal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72544, 'spa', 'Hacer cometer adulterio', 'Hacer cometer adulterio: sentido causativo o indirecto que aparece en Mt 5:32, donde quien repudia a su mujer sin causa válida ''hace que ella cometa adulterio'' (μοιχευθῆναι, infinitivo aoristo pasivo). La morfología pasiva aquí conlleva fuerza causativa: el esposo que repudia, no la mujer, carga con la responsabilidad moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72548, 'spa', 'Quien comete adulterio', 'Adúltero, persona que comete infidelidad sexual en el matrimonio. El término aparece en catálogos morales (Lc 18:11, donde el fariseo se compara; 1 Co 6:9, entre los excluidos del reino de Dios) y en advertencias de juicio divino (Heb 13:4). Aunque μοιχός es gramaticalmente masculino, designa de modo inclusivo a todo aquel que quebranta el pacto conyugal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72549, 'spa', 'Con dificultad, apenas', 'Con dificultad, apenas, a duras penas; indica una acción lograda solo por escaso margen o con gran esfuerzo. En Hechos, Lucas emplea μόλις repetidamente en contextos náuticos y de control de multitudes: Pablo y Bernabé apenas pudieron detener a los licaonios de ofrecer sacrificios (Hch 14:18), la nave navegó con dificultad más allá de Gnido (Hch 27:7), llegaron a duras penas a Buenos Puertos (Hch 27:8) y la tripulación apenas pudo sujetar el esquife (Hch 27:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72550, 'spa', 'Deidad pagana amonita', 'En el discurso de Esteban en Hechos 7:43, Moloc aparece como evidencia de la idolatría persistente de Israel durante el período del desierto. La acusación es devastadora: mientras profesaban devoción a Yahvé, los israelitas cargaban imágenes de esta deidad detestable asociada con el sacrificio de niños. Esteban demuestra así el patrón constante de rebeldía del pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72551, 'spa', 'Manchar o contaminar', 'Contaminar, manchar o ensuciar, volviendo ritual o moralmente impuro. En 1 Corintios 8:7 se refiere a la contaminación de la conciencia por comer alimentos comprometidos. En Apocalipsis 3:4 y 14:4 alude a la pureza moral y sexual: no manchar las vestiduras ni contaminarse con inmoralidad. El griego μολύνω abarca tanto la impureza ceremonial como la corrupción moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72552, 'spa', 'Contaminación moral integral', 'En 2 Corintios 7:1, Pablo llama a una limpieza integral de toda contaminación que afecte tanto la carne como el espíritu. La evidencia interlingüística subraya la polución y la mancha. La exhortación sigue a su advertencia contra asociarse con incrédulos. La doble referencia a carne y espíritu indica que la impureza amenaza ambas dimensiones del creyente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72553, 'spa', 'Queja interpersonal', 'En Colosenses 3:13, Pablo aborda el manejo de quejas dentro de la comunidad cristiana mediante la paciencia y el perdón. La evidencia interlingüística enfatiza la queja y el agravio. Pablo asume que surgirán causas genuinas de queja entre los creyentes y su respuesta es clara: sobrellevarse mutuamente con paciencia y perdonar libremente, así como el Señor los perdonó a ellos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72555, 'spa', 'Unigénito', 'El único descendiente de un padre, o más ampliamente, aquel que es engendrado de manera única y sin igual. Los Sinópticos describen hijos únicos en situaciones desesperadas: el hijo único de la viuda (Lucas 7:12), la hija única de Jairo (Lucas 8:42) y el único hijo epiléptico de un padre angustiado (Lucas 9:38). El uso juanino transforma la palabra teológicamente: Jesús es el μονογενής del Padre, ''lleno de gracia y verdad'' (Juan 1:14), revelación exclusiva del Dios invisible (Juan 1:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72557, 'spa', 'solo, solamente', 'Adverbio restrictivo que significa ''solo'', ''solamente'' o ''únicamente'', limitando el alcance de una afirmación a una sola condición, acción o entidad. Omnipresente en el NT: «solamente cree» (Mr 5:36), «solamente di la palabra» (Mt 8:8), «solo tocar su manto» (Mt 9:21), «no solo para los judíos» (Ro 3:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72558, 'spa', 'solo (en soledad)', 'Sentido espacial-perceptivo infrecuente que significa ''solo'' en el sentido de soledad física, no de restricción lógica. Se circunscribe al relato de la Transfiguración: al desvanecerse la visión, los discípulos ven «a Jesús solo» (μόνον, Mt 17:8; Mr 9:8). El español ''solo'' pasa aquí de lo restrictivo a lo existencial, describiendo la ausencia de acompañantes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72559, 'spa', 'Solo, a solas', 'Solo, a solas. Sentido mas frecuente: solo, sin compania, solitario, sin la presencia o ayuda de otros. Jesus se retira ''solo'' a orar (Mt 14:23), ensena que el ser humano no vive ''solo'' de pan (Mt 4:4) y declara que nadie conoce el dia ''sino solo el Padre'' (Mt 24:36). El espanol ''solo'' y el aleman ''allein'' expresan consistentemente este sentido de soledad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72560, 'spa', 'Unico, singular, solo', 'Unico, singular, solo. Sentido de gran peso teologico: el unico, singular, sin par. Se aplica a Dios como ''el unico Dios verdadero'' (Jn 17:3), ''el unico Dios sabio'' (Ro 16:27) y ''el unico Soberano'' (1 Ti 6:15). El espanol ''unico'' y el aleman ''einzigen'' distinguen este sentido de la mera soledad: afirma unicidad ontologica y sustenta declaraciones doxologicas y confesionales clave en las epistolas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72562, 'spa', 'Solamente, exclusivamente', 'Solamente, exclusivamente. Fuerza adverbial restrictiva o exclusiva: solamente, nada mas que. Los panes de la proposicion eran licitos ''solo'' para los sacerdotes (Mt 12:4; Lc 6:4); Pablo pregunta si ''solo'' el y Bernabe carecen del derecho a no trabajar (1 Co 9:6). Aqui μόνος funciona como limitador de alcance, no como descripcion de soledad fisica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72570, 'spa', 'Soledad por desamparo', 'En 1 Timoteo 5:5, la viuda verdadera es caracterizada como alguien que ha quedado completamente sola. La evidencia interlingüística subraya el aislamiento y el abandono. El participio perfecto pasivo enfatiza su estado continuo de soledad, privada de apoyo familiar. Este aislamiento constituye el criterio para recibir asistencia eclesial, distinguiéndola de viudas con parientes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72571, 'spa', 'Forma visible', 'La forma externa, figura o manifestación visible que expresa genuinamente la realidad interior. Marcos 16:12 describe a Jesús apareciendo en una μορφή diferente tras la resurrección. Filipenses 2:6-7 la emplea para la forma divina de Cristo y luego su forma de siervo: no mera apariencia, sino manifestación auténtica de lo que realmente es.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72572, 'spa', 'Formación espiritual interior', 'En Gálatas 4:19, Pablo emplea una metáfora maternal: sufre dolores de parto hasta que Cristo sea formado en sus hijos espirituales. La evidencia interlingüística destaca el proceso de formación y configuración. El aoristo pasivo subjuntivo sugiere una formación definitiva y completa, donde el carácter y la semejanza de Cristo toman forma clara en la vida interior de los creyentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72574, 'spa', 'Fabricación idolátrica del becerro', 'En Hechos 7:41, este compuesto específico describe la apostasía del becerro de oro en el Sinaí. Las traducciones interlingüísticas identifican consistentemente la acción: hicieron un becerro. El uso de este término técnico por parte de Esteban intensifica la tragedia: mientras Moisés comulgaba con Dios recibiendo la ley vivificante, el pueblo deliberadamente fabricó un ídolo, rechazando al Dios verdadero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72575, 'spa', 'Becerro o novillo', 'Animal bovino joven, becerro o novillo, usado en el NT tanto para la matanza festiva como para el sacrificio ritual. En Lucas 15:23, 27 y 30, el becerro gordo (μόσχος) es sacrificado para celebrar el retorno del hijo pródigo, representando generosidad desbordante y gozo por la restauración. En Hebreos 9:12 y 9:19, los becerros aparecen en el contexto sacrificial de los ritos de sangre del antiguo pacto, que el autor contrasta con el sacrificio superior de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72578, 'spa', 'Fatiga laboriosa', 'Afán, fatiga o esfuerzo penoso marcado por el cansancio y la tensión. Pablo usa μόχθος para describir su trabajo manual mientras ejercía el ministerio, laborando «noche y día» para no ser carga a las iglesias (1 Ts 2:9; 2 Ts 3:8). En 2 Corintios 11:27 forma parte de su catálogo de sufrimientos apostólicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72579, 'spa', 'Músico profesional', 'En Apocalipsis 18:22, los músicos figuran entre los sonidos que desaparecerán de Babilonia en el juicio divino. La evidencia multilingüe identifica consistentemente a músicos profesionales o personas hábiles en las artes musicales. La visión de Juan sobre el silencio incluye el cese de arpistas, músicos, flautistas y trompeteros, es decir, todos los sonidos de celebración, cultura y comercio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72580, 'spa', 'Médula ósea', 'En Hebreos 4:12, la médula se emplea en una poderosa metáfora del poder penetrante de las Escrituras. La frase «coyunturas y tuétanos» es paralela a «alma y espíritu», representando los aspectos más profundos y ocultos de la existencia física y espiritual. La Palabra viviente de Dios traspasa las realidades superficiales para discernir los pensamientos e intenciones del corazón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72581, 'spa', 'Iniciación en secretos', 'En Filipenses 4:12, Pablo afirma haber sido iniciado en el secreto del contentamiento a través de experiencias diversas. Pablo emplea el lenguaje de los misterios: ha sido iniciado, ha aprendido el misterio. Pero a diferencia de los ritos paganos, su iniciación provino de vivencias de abundancia y escasez, todas capacitadas por Cristo, revelándole el secreto de la verdadera satisfacción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72582, 'spa', 'Mito o fábula', 'Mito, fábula o relato religioso ficticio, siempre empleado negativamente en el NT para describir falsas enseñanzas que distraen de la sana doctrina. Pablo opone los mitos a la verdad del evangelio (1 Tim 1:4; 4:7; 2 Tim 4:4; Tit 1:14), y Pedro distancia enfáticamente el testimonio apostólico de los «mitos ingeniosamente inventados» (2 Pe 1:16). El término designa narrativas fabricadas que compiten con la revelación auténtica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72583, 'spa', 'Rugir con poder', 'En Apocalipsis 10:3, la voz del ángel poderoso se describe como el rugido de un león, desencadenando siete truenos. La comparación con el rugido leonino transmite autoridad, poder y majestad sobrecogedora. No se trata de un anuncio ordinario, sino de una proclamación cósmica que estremece la creación, representando la comunicación divina de abrumadora autoridad.');